#!/usr/bin/env python3
import subprocess
import sys

def check_crontab():
    try:
        # Try to list crontab entries
        result = subprocess.run(['crontab', '-l'], capture_output=True, text=True)

        if result.returncode == 0:
            crontab_content = result.stdout.strip()
            print("Current crontab entries:")
            print(crontab_content)

            # Check if our Docker cleanup job is already scheduled
            if 'docker_weekly_cleanup.sh' in crontab_content:
                print("\n✓ Docker weekly cleanup cron job is already set up.")
                return True
            else:
                print("\n✗ Docker weekly cleanup cron job is not found.")
                return False
        else:
            print("No crontab entries found or unable to access crontab.")
            return False

    except FileNotFoundError:
        print("Crontab command not found.")
        return False
    except Exception as e:
        print(f"Error checking crontab: {e}")
        return False

if __name__ == "__main__":
    check_crontab()

